namespace sv_30670641a49b463dab28ed10649633fc.Services;

public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A - Downtown",
            ["WH-002"] = "Warehouse B - Airport",
            ["WH-003"] = "Warehouse C - Harbor"
        };

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        OnChange = null;
    }
}

namespace sv_30670641a49b463dab28ed10649633fc.Services;

public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastLowStockCount;
    private CancellationTokenSource? _pollCts;
    private Timer? _pollTimer;
    private string? _pollingWarehouseId;

    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Fired when new alert data arrives. All subscribed components should re-render.
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling every 10 seconds for the given warehouse.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        StopPolling();
        _pollingWarehouseId = warehouseId;
        _pollCts = new CancellationTokenSource();

        // Fire immediately, then every 10 seconds
        _pollTimer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    /// <summary>
    /// Switches the polling target to a new warehouse without restarting the timer cycle.
    /// </summary>
    public void UpdatePollingWarehouse(string warehouseId)
    {
        if (_pollTimer is null)
        {
            StartPolling(warehouseId);
            return;
        }

        _pollingWarehouseId = warehouseId;
        // Immediately fetch for the new warehouse
        _ = PollAsync();
    }

    public void StopPolling()
    {
        _pollCts?.Cancel();
        _pollTimer?.Dispose();
        _pollTimer = null;
        _pollCts = null;
        _pollingWarehouseId = null;
    }

    private async Task PollAsync()
    {
        if (_pollingWarehouseId is null) return;

        var count = await GetLowStockCountAsync(_pollingWarehouseId);
        _lastLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        StopPolling();
        OnAlertDataChanged = null;
    }
}

