@page "/dashboard"
@rendermode InteractiveServer
@using sv_30670641a49b463dab28ed10649633fc.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @CountClass">@AlertService.LastLowStockCount</p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Auto-refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Selected Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
                <p class="text-muted">@WarehouseState.CurrentWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">● Active</p>
                <p class="text-muted">Polling while dashboard is visible</p>
            </div>
        </div>
    </div>
</div>

@code {
    private string CountClass => AlertService.LastLowStockCount switch
    {
        > 10 => "text-danger",
        > 5 => "text-warning",
        _ => "text-success"
    };

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertChanged;

        // Start polling when the dashboard becomes visible
        AlertService.StartPolling(WarehouseState.CurrentWarehouseId);
    }

    private void OnWarehouseChanged()
    {
        // When the warehouse changes, switch polling target immediately
        AlertService.UpdatePollingWarehouse(WarehouseState.CurrentWarehouseId);
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when user navigates away from the dashboard
        AlertService.StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertChanged;
    }
}

