        // Start polling when the dashboard becomes visible
        AlertService.StartPolling(WarehouseState.CurrentWarehouseId);
    }

    private void OnWarehouseChanged()
    {
        // When the warehouse changes, switch polling target immediately
        AlertService.UpdatePollingWarehouse(WarehouseState.CurrentWarehouseId);
        InvokeAsync(StateHasChanged);
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when user navigates away from the dashboard
        AlertService.StopPolling();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertChanged;
    }
}

